import random
import itertools

n = 25

def has_cycle_of_length(edges, length):
    """Check if the graph has a cycle of given length using BFS limited depth"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # For each starting vertex, do BFS up to depth length
    for start in range(n):
        # BFS with parent tracking
        queue = [(start, 0, -1)]
        visited = {start: 0}
        while queue:
            node, dist, parent = queue.pop(0)
            if dist >= length:
                continue
            for nb in adj[node]:
                if nb == parent:
                    continue
                if nb in visited:
                    # Found a cycle
                    cycle_len = visited[node] + visited[nb] + 1
                    if cycle_len <= length:
                        return True
                else:
                    visited[nb] = dist + 1
                    queue.append((nb, dist + 1, node))
    return False

def has_any_small_cycle(edges, max_len=6):
    """Check if graph has any cycle of length <= max_len"""
    for l in range(3, max_len + 1):
        if has_cycle_of_length(edges, l):
            return True
    return False

def check_degrees(edges):
    deg = [0] * n
    for u, v in edges:
        deg[u] += 1
        deg[v] += 1
    return all(3 <= d <= 5 for d in deg)

# Try a constructive approach: start with empty graph, add edges greedily
# while maintaining degree and girth constraints

def try_construct(seed, max_attempts=100000):
    random.seed(seed)
    edges = []
    adj = {i: set() for i in range(n)}
    deg = [0] * n

    # Order vertices by some heuristic
    vertices = list(range(n))

    # Try to add edges one by one
    for attempt in range(max_attempts):
        if all(3 <= d <= 5 for d in deg):
            # Check girth
            if not has_any_small_cycle(edges):
                return edges

        # Find vertices that need more edges
        candidates = [v for v in range(n) if deg[v] < 5]
        if not candidates:
            break

        # Pick a vertex with lowest degree (that still needs edges)
        v = min(candidates, key=lambda x: deg[x])

        # Find possible neighbors
        possible = [u for u in range(n) if u != v and u not in adj[v] and deg[u] < 5]

        if not possible:
            # Backtrack? For now, just break
            break

        # Shuffle and try
        random.shuffle(possible)
        added = False
        for u in possible:
            # Check if adding this edge creates a small cycle
            test_edges = edges + [(min(v, u), max(v, u))]
            if not has_any_small_cycle(test_edges):
                edges.append((min(v, u), max(v, u)))
                adj[v].add(u)
                adj[u].add(v)
                deg[v] += 1
                deg[u] += 1
                added = True
                break

        if not added:
            # Can't add more edges from v, try another vertex
            # Mark v as "stuck" temporarily
            pass

    return None

# Try multiple seeds
for seed in range(100):
